  <div class="grid">
    <div class="card">
      <div class="card-title">Server Software</div>
      <div class="card-value" style="font-size: 14px;">${t.server.software}</div>
    </div>
    <div class="card">
      <div class="card-title">Memory Limit</div>
      <div class="card-value">${t.server.memory_limit}</div>
    </div>
    <div class="card">
      <div class="card-title">Max Upload Size</div>
      <div class="card-value">${t.server.max_upload_size_formatted}</div>
    </div>
    <div class="card">
      <div class="card-title">Database Size</div>
      <div class="card-value">${t.database.size_formatted}</div>
      <div class="card-detail">${t.database.tables_count} tables</div>
    </div>
  </div>

